class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.end = True
    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.end

class EventEmitter {
  constructor() { this.events = {}; }
  on(event, listener) {
    if (!this.events[event]) this.events[event] = [];
    this.events[event].push(listener);
  }
  emit(event, ...args) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(...args));
    }
  }
  off(event, listener) {
    if (this.events[event]) {
      this.events[event] = this.events[event].filter(l => l !== listener);
    }
  }
}

function throttle(func, limit) {
  let inThrottle = false;
  return function(...args) {
    if (!inThrottle) {
      func.apply(this, args);
      inThrottle = true;
      setTimeout(() => inThrottle = false, limit);
    }
  };
}

def knapsack_memo(weights, values, capacity, n, memo=None):
    if memo is None: memo = {}
    if n == 0 or capacity == 0:
        return 0
    state = (n, capacity)
    if state in memo:
        return memo[state]
    if weights[n-1] <= capacity:
        result = max(
            values[n-1] + knapsack_memo(weights, values, capacity - weights[n-1], n-1, memo),
            knapsack_memo(weights, values, capacity, n-1, memo)
        )
    else:
        result = knapsack_memo(weights, values, capacity, n-1, memo)
    memo[state] = result
    return result

